require __DIR__.'/../includes/bootstrap.php'; leader_required(); $leader=staff($pdo); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); if(($_POST['action']??'')==='all_read'){$pdo->prepare("UPDATE notifications SET is_read=1 WHERE user_id=?")->execute([(int)$leader['id']]);$msg='All notifications marked as read.';}}
$q=$pdo->prepare("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 80");$q->execute([(int)$leader['id']]);$rows=$q->fetchAll();$unread=0;foreach($rows as $r)$unread+=(int)!$r['is_read'];
$page_title='Notifications';require __DIR__.'/../includes/header.php';?>
<div><?php require __DIR__.'/../includes/leader_sidebar.php';?><main class="main"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-btn" data-sidebar-toggle><i class="bi bi-list"></i></button><div><h1>Notifications</h1><p>Appointment, pastoral and church-operation alerts sent to your account.</p></div></div><?php if($unread):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="all_read"><button class="btn btn-sm btn-outline-secondary">Mark all read</button></form><?php endif;?></header><div class="content"><?php if($msg):?><div class="alert alert-success"><?=e($msg)?></div><?php endif;?><div class="cardx p-4"><div class="d-grid gap-2"><?php foreach($rows as $r):?><div class="p-3 rounded-4 border <?=$r['is_read']?'':'bg-light'?>"><div class="d-flex justify-content-between gap-3"><strong><?=e($r['title'])?></strong><small class="text-muted"><?=e(date('d M Y, g:i A',strtotime($r['created_at'])))?></small></div><p class="mb-0 mt-2 small" style="white-space:pre-wrap"><?=e($r['message'])?></p></div><?php endforeach;?><?php if(!$rows):?><div class="empty">No notifications yet.</div><?php endif;?></div></div></div></main></div>
